                elseif($key==='robots_exposure'){$u=rtrim($base,'/').'/robots.txt';$r=HttpClient::probe($u,12,64000);$body=(string)($r['body']??'');$sensitive=[];foreach(preg_split('/\R/',$body)?:[] as $line){if(!preg_match('/^\s*Disallow\s*:\s*(\S+)/i',$line,$m))continue;$path=pb_strtolower($m[1]);if(preg_match('#(admin|backup|config|secret|private|database|db|phpmyadmin)#',$path))$sensitive[]=$m[1];}$bad=(int)($r['status']??0)===200&&!empty($sensitive);$ev=['status'=>$r['status']??0,'sensitive_hints'=>array_slice($sensitive,0,20),'body_sha256'=>$r['sha256']??null];$event=self::event($runId,$case,$bad?'finding':'passed','robots.txt must not be treated as access control and should avoid advertising sensitive locations.',$bad?'Sensitive-looking path hints found in public robots.txt.':'No sensitive path hint was identified in the public robots file.','very_easy',$ev);if(!$bad)$passed++;else{$failed++;$findings+=self::finding($run,$case,$event,'Sensitive path hints in robots.txt','robots.txt exposure','Public path hints can assist enumeration, although robots.txt itself is not a protection mechanism.','Only public robots.txt was read; no hinted path was requested.','Remove unnecessary sensitive path hints and enforce server-side authorization on every path.','very_easy',$ev);}}
