                        $bad=0;foreach((array)$r['tests'] as $t)if(is_array($t)&&in_array((string)($t['state']??$t['status']??''),['failed','error'],true))$bad++;$ev=['browser_run_id'=>$r['run_id']??null,'tests_count'=>count((array)$r['tests']),'failed'=>$bad,'screenshots'=>array_slice((array)$r['screenshots'],0,12),'warnings'=>array_slice($warn,0,12)];$event=self::event($runId,$case,$bad?'finding':'passed','واجهة تعمل على Desktop/Tablet/Mobile بدون أخطاء Browser QA واضحة.',$bad?$bad.' اختبار Browser QA فشل.':'Browser QA اكتمل بدون فشل معلن.',$bad?'easy':'unknown',$ev);if(!$bad)$passed++;else{$failed++;$findings+=self::finding($run,$case,$event,'مشكلات واجهة/متصفح في Browser QA','Browser QA failures','قد تؤثر على الاستخدام أو التسليم حسب الاختبارات الفاشلة.','Evidence يحتوي معرف تشغيل المتصفح والملخص والصور المرجعية فقط.','افتح تفاصيل Browser QA وأصلح الاختبارات الفاشلة ثم أعد التشغيل.','easy',$ev);}}}
