    private static function event(int $runId,array $case,string $state,string $expected,string $actual,string $difficulty,array $ev):int{db()->prepare('INSERT INTO security_test_events(run_id,test_case_id,test_key,state,expected_text,actual_text,difficulty,evidence_json,started_at,finished_at) VALUES (?,?,?,?,?,?,?,?,NOW(),NOW())')->execute([$runId,(int)$case['id'],(string)$case['test_key'],$state,$expected,$actual,$difficulty,$ev?j($ev):null]);return (int)db()->lastInsertId();}
    private static function finding(array $run,array $case,int $eventId,string $title,string $description,string $impact,string $proof,string $remediation,string $difficulty,array $ev):int{
        $key=(string)$case['test_key'].':'.hash('sha256',(string)$run['target_id'].'|'.$title);
        if(preg_match('/^retest_finding_(\d+)$/',(string)($run['run_type']??''),$rm)){
            try{
                $original=SecurityLabService::finding((int)$rm[1]);
                if((string)$original['finding_key']===$key){
                    db()->prepare("UPDATE security_findings SET status='reopened',test_event_id=?,description_text=?,impact_text=?,proof_text=?,remediation_text=?,evidence_json=?,last_verified_at=NOW() WHERE id=?")->execute([$eventId,$description,$impact,$proof,$remediation,$ev?j($ev):null,(int)$original['id']]);
                    if(in_array((string)$case['severity_if_failed'],['critical','high'],true))self::notifyFinding($run,(int)$original['id'],$title,(string)$case['severity_if_failed']);
                    return 1;
                }
            }catch(Throwable){}
        }
        db()->prepare("INSERT INTO security_findings(run_id,target_id,test_event_id,project_id,finding_key,title_ar,technical_name,severity,difficulty,status,description_text,impact_text,proof_text,remediation_text,evidence_json,last_verified_at) VALUES (?,?,?,?,?,?,?,?,?,'open',?,?,?,?,?,NOW())")->execute([(int)$run['id'],(int)$run['target_id'],$eventId,$run['project_id']?(int)$run['project_id']:null,pb_substr($key,0,190),pb_substr($title,0,255),(string)$case['label_ar'],(string)$case['severity_if_failed'],$difficulty,$description,$impact,$proof,$remediation,$ev?j($ev):null]);
        $id=(int)db()->lastInsertId();if(in_array((string)$case['severity_if_failed'],['critical','high'],true))self::notifyFinding($run,$id,$title,(string)$case['severity_if_failed']);return 1;
    }
    private static function notifyFinding(array $run,int $findingId,string $title,string $severity):void{$msg='عماد: اكتشفت Finding '.strtoupper($severity).' #'.$findingId.' في '.(string)$run['target_label'].': '.$title.'. راجع صفحة الاختبارات قبل التسليم.';try{Notifications::add('critical','security','Finding أمني مهم',$msg,'security_finding',(string)$findingId);}catch(Throwable){}if(setting('security.notify_owner_whatsapp','1')==='1')try{CommunicationGateway::agentToOwner('emad',$msg,'whatsapp',false,true);}catch(Throwable $e){error_log('ELMETR security owner notify: '.Security::redactSecrets($e->getMessage(),180));}}
    private static function notifyChallenge(array $run,string $challenge):void{$msg='عماد: توقفت في اختبار '.(string)$run['target_label'].' بسبب حماية/تحقق بشري ('.pb_substr($challenge,0,160).'). مطلوب تدخل المالك؛ لم أحاول تجاوزها تلقائيًا.';try{Notifications::add('warning','security','الاختبار يحتاج تدخل المالك',$msg,'security_run',(string)$run['id']);}catch(Throwable){}if(setting('security.notify_owner_whatsapp','1')==='1')try{CommunicationGateway::agentToOwner('emad',$msg,'whatsapp',false,true);}catch(Throwable $e){error_log('ELMETR security challenge notify: '.Security::redactSecrets($e->getMessage(),180));}}
    private static function finishRetestIfAny(int $runId,int $findings,string $final):void{
        $q=db()->prepare("SELECT * FROM security_retests WHERE run_id=? AND state IN ('queued','running') ORDER BY id DESC LIMIT 1");$q->execute([$runId]);$r=$q->fetch();if(!$r)return;
        $f=SecurityLabService::finding((int)$r['finding_id']);$testKey=explode(':',(string)$f['finding_key'],2)[0];
        $e=db()->prepare("SELECT state FROM security_test_events WHERE run_id=? AND test_key=? ORDER BY id DESC LIMIT 1");$e->execute([$runId,$testKey]);$eventState=(string)($e->fetchColumn()?:'');
        if($final==='blocked_owner'||in_array($eventState,['blocked','error','manual_required','skipped',''],true))$state='blocked';
        elseif($eventState==='finding')$state='failed';
        elseif($eventState==='passed')$state='passed';
        else $state=$findings>0?'failed':'blocked';
        $txt=$state==='passed'?'إعادة الاختبار المحددة لم تعثر على نفس Finding؛ تم التحقق من الإصلاح.':($state==='failed'?'المشكلة مازالت قابلة للرصد في إعادة الاختبار المحددة.':'إعادة الاختبار لم تكتمل بنتيجة حاسمة أو توقفت بسبب حماية/تدخل مطلوب.');
        db()->prepare('UPDATE security_retests SET state=?,result_text=?,completed_at=NOW() WHERE id=?')->execute([$state,$txt,(int)$r['id']]);
        if($state==='passed')db()->prepare("UPDATE security_findings SET status='fixed',fixed_at=NOW(),last_verified_at=NOW() WHERE id=?")->execute([(int)$f['id']]);
        elseif($state==='failed')db()->prepare("UPDATE security_findings SET status='reopened',fixed_at=NULL,last_verified_at=NOW() WHERE id=?")->execute([(int)$f['id']]);
    }
}
